SINA_SMART["immuno1-innate"] = {"lecture":"immuno1-innate","title":"Innate immunity","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"immuno1-innate:e0","text":"Innate immunity: ~800 million years old; rapid, non-specific, no improvement.","topic":"The big picture","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"immuno1-innate:e1","text":"Three mechanisms: barriers, chemical agents, effector cells.","topic":"The big picture","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"immuno1-innate:e2","text":"Skin pH 3-5; mucus and cilia (defective in cystic fibrosis).","topic":"Barriers","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"immuno1-innate:e3","text":"Lysozyme: bacterial walls; lactoferrin: iron chelation.","topic":"Barriers","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"immuno1-innate:e4","text":"AMPs: 12-50 aa, cationic, make pores.","topic":"Barriers","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"immuno1-innate:e5","text":"α-defensins: neutrophils, Paneth cells; β-defensins: skin, airways.","topic":"Barriers","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"immuno1-innate:e6","text":"Surfactant SP-A, SP-D: primitive opsonins.","topic":"Barriers","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"immuno1-innate:e7","text":"Commensal flora: competition, colicins, immune maturation.","topic":"Barriers","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"immuno1-innate:e10","text":"PRRs (e.g. TLRs) recognise PAMPs.","topic":"Humoral and cellular components","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"immuno1-innate:e8","text":"Innate-like lymphocytes: NK, NKT, γδ T, B1.","topic":"Humoral and cellular components","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"immuno1-innate:e9","text":"NK: KIR sees MHC I; kills 'missing self'.","topic":"Humoral and cellular components","sec":2,"importance":"core","highYield":"insufficient-source"}],"vmap":{},"mlevel":{"qjkbly":"a","lw8yn4":"a","d1gmu5":"a","1rm7c9u":"a","106ujji":"a","4ugjg5":"a","103md9h":"a","y9n0ku":"a","cqyfm3":"a","jdj4c7":"a","pbsp9d":"a","1k7swgq":"a"},"mapCounts":{"verified":0,"auto":12,"ambiguous":0,"missing":0},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"immuno1-innate:e0":{"s":0,"u":["Innate immunity: ~800 million years old; rapid, non-specific, no improvement.","Innate immunity appeared about 800 million years ago and is found throughout living organisms.","It is a species-specific state of natural resistance: rapid (hours) , non-specific , with constant recognition that does not improve on re-exposure, unlike adaptive immunity (slow, days to weeks; specific repertoire; improves)."],"dp":[]},"immuno1-innate:e1":{"s":0,"u":["Three mechanisms: barriers, chemical agents, effector cells.","It uses three mechanisms: barriers , non-specific chemical agents (complement, cytokines) and non-specific effector cells (neutrophils, macrophages, NK cells)."],"dp":[]},"immuno1-innate:e2":{"s":1,"u":["Skin pH 3-5; mucus and cilia (defective in cystic fibrosis).","Mechanical : the skin delays entry, and its acidic surface ( pH 3-5 ) inhibits growth; mucus (mucins) coats microbes and ciliated cells sweep them out (in cystic fibrosis , the CFTR defect dehydrates mucus, cilia cannot clear it, and bacterial colonisation and inflammation follow)."],"dp":[]},"immuno1-innate:e3":{"s":1,"u":["Lysozyme: bacterial walls; lactoferrin: iron chelation.","Antimicrobial molecules : lysozyme (destroys the walls of Gram+ and Gram− bacteria; abundant in tears, saliva, nasal secretions), lactoferrin (chelates iron needed for bacterial growth), defensins ('natural antibiotics'), cathelicidins (e.g."],"dp":[]},"immuno1-innate:e4":{"s":1,"u":["AMPs: 12-50 aa, cationic, make pores.","Antimicrobial peptides : 12-50 amino acids, mainly cationic , active on bacteria, fungi and viruses; they make pores in microbial membranes and interfere with DNA, RNA and protein synthesis. α-defensins come from neutrophils and intestinal Paneth cells ; β-defensins from epithelia of skin and airways."],"dp":[]},"immuno1-innate:e5":{"s":1,"u":["α-defensins: neutrophils, Paneth cells; β-defensins: skin, airways.","Antimicrobial peptides : 12-50 amino acids, mainly cationic , active on bacteria, fungi and viruses; they make pores in microbial membranes and interfere with DNA, RNA and protein synthesis. α-defensins come from neutrophils and intestinal Paneth cells ; β-defensins from epithelia of skin and airways."],"dp":[]},"immuno1-innate:e6":{"s":1,"u":["Surfactant SP-A, SP-D: primitive opsonins.","LL-37), surfactant proteins SP-A and SP-D (primitive opsonins), and interferons."],"dp":[]},"immuno1-innate:e7":{"s":1,"u":["Commensal flora: competition, colicins, immune maturation.","Commensal flora : helps digestion (vitamins, fatty acids), competes with pathogens for nutrients and iron, blocks access to the epithelium, produces antibacterial substances (colicins) and matures the immune system."],"dp":[{"h":"Why antibiotics can cause C. difficile colitis","t":"Commensal gut bacteria occupy space and nutrients and produce antibacterial substances, keeping pathogens in check. Broad-spectrum antibiotics wipe out much of this flora, removing that barrier; resistant Clostridioides difficile can then overgrow and release toxins, causing severe diarrhoea. It shows that the microbiota is part of innate defence. Source: the tutorial's commensal flora slide."}]},"immuno1-innate:e10":{"s":2,"u":["PRRs (e.g. TLRs) recognise PAMPs.","Innate cells recognise conserved microbial patterns ( PAMPs ) with pattern recognition receptors (PRRs) such as Toll-like receptors, triggering phagocytosis and inflammation."],"dp":[]},"immuno1-innate:e8":{"s":2,"u":["Innate-like lymphocytes: NK, NKT, γδ T, B1.","Cells: phagocytes (neutrophils, monocytes/macrophages, dendritic cells), mast cells and innate-like lymphocytes : NK , NKT , γδ T and B1 cells.","Innate cells recognise conserved microbial patterns ( PAMPs ) with pattern recognition receptors (PRRs) such as Toll-like receptors, triggering phagocytosis and inflammation."],"dp":[]},"immuno1-innate:e9":{"s":2,"u":["NK: KIR sees MHC I; kills 'missing self'.","NK cells (up to 15% of blood lymphocytes, no TCR or BCR) balance activating (KAR) and inhibitory ( KIR , recognising MHC class I) receptors: they spare normal cells but kill cells showing missing self (lost MHC I, as in tumours or virus-infected cells), modified self , or foreign MHC I (alloreactivity); they act by natural cytotoxicity, ADCC and cytokines."],"dp":[]}},"meta":{"qjkbly":{"a":"recall","vg":"immuno1-innate:e0/recall/1"},"lw8yn4":{"a":"relationship","vg":"immuno1-innate:e0/relationship/1"},"d1gmu5":{"a":"recall","vg":"immuno1-innate:e2/recall/1"},"1rm7c9u":{"a":"recall","vg":"immuno1-innate:e2/recall/2"},"106ujji":{"a":"recall","vg":"immuno1-innate:e3/recall/1"},"4ugjg5":{"a":"recall","vg":"immuno1-innate:e3/recall/2"},"103md9h":{"a":"recall","vg":"immuno1-innate:e4/recall/1"},"y9n0ku":{"a":"recall","vg":"immuno1-innate:e5/recall/1"},"cqyfm3":{"a":"recall","vg":"immuno1-innate:e6/recall/1"},"jdj4c7":{"a":"recall","vg":"immuno1-innate:e7/recall/1"},"pbsp9d":{"a":"recall","vg":"immuno1-innate:e9/recall/1"},"1k7swgq":{"a":"recall","vg":"immuno1-innate:e10/recall/1"}},"explRev":"9b0416feea99"};
